/** WS-REG-DET-INFOICA: un movimiento del LOG general de compensación (160 bytes). */
public record MovimientoLog(
        int csiOrigen,             // 9(02)  88 RDI-CSI-ORI-VAL 2,4,10
        int nodoOrigen,
        int csiDestino,            // 9(02)  88 RDI-CSI-DES-VAL 2,4,10
        char tipoDispositivo, int sucursalOrigen, String cajaOrigen,   // NOM-EST redefinido
        LocalDate fechaGeneracion, LocalTime horaGeneracion,
        int aplOrigen, int aplDestino,
        EstatusTrn estatus,        // 9(02)
        CodigoServicio codServicio,// 9(02)
        int subServicio,
        String cuentaDestino,      // X(20): conserva ceros; sucursal y número en posiciones 10-20
        BigDecimal importe,        // 9(16)V99 -> escala 2
        int moneda,
        LocalDate fechaContable,
        String claveAutorizacion,  // X(20): llave de agrupación
        long numTransaccion,
        String cuentaAcceso, String referencia,
        String raw) {}             // el registro viaja íntegro a TEMPFILE y a S028

public enum EstatusTrn {
    ENVIADO(1), APLICADO(2), OPERADO(3), DENEGADO(4), PENDIENTE(5);
    final int codigo;
    EstatusTrn(int c) { codigo = c; }
}

/** Interpretación contable fija del código de servicio. */
public enum CodigoServicio {
    CARGO(10), ELIM_CARGO(11), ABONO(20), ELIM_ABONO(21);
    final int codigo;
    CodigoServicio(int c) { codigo = c; }

    /** Es la eliminación (reverso) de 'otro'. Se usa para netear en 2543. */
    boolean revierte(CodigoServicio otro) {
        return switch (this) {
            case ELIM_CARGO -> otro == CARGO;
            case ELIM_ABONO -> otro == ABONO;
            case CARGO      -> otro == ELIM_CARGO;
            case ABONO      -> otro == ELIM_ABONO;
        };
    }
}

